See the License for the specific language governing permissions and
limitations under the License.
*/

import { MatrixClient, MatrixEvent } from "matrix-js-sdk/src/matrix";

import { VoiceBroadcastInfoState } from "..";

export const shouldDisplayAsVoiceBroadcastRecordingTile = (
    state: VoiceBroadcastInfoState,
    client: MatrixClient,
    event: MatrixEvent,
): boolean => {
    const userId = client.getUserId();
    // Return true if:
    // 1. The current user is the sender (userId is not null and matches the sender)
    // 2. The broadcast has NOT stopped (state is not VoiceBroadcastInfoState.Stopped)
    return userId === event.getSender() && state !== VoiceBroadcastInfoState.Stopped;
};
EOF
